            ['start_time' => 164.05, 'end_time' => 168.91, 'target_text' => 'No one knows it." So, therefore, appreciate each other.', 'source_text' => 'Tiada siapa pun yang mengetahuinya." Maka oleh itu, hargailah antara satu sama lain.', 'order' => 41],
            ['start_time' => 169.01, 'end_time' => 171.15, 'target_text' => 'Appreciate your family members.', 'source_text' => 'Hargailah ahli keluarga anda.', 'order' => 42],
            ['start_time' => 171.25, 'end_time' => 173.03, 'target_text' => 'Appreciate your children.', 'source_text' => 'Hargailah anak-anak anda.', 'order' => 43],
            ['start_time' => 173.13, 'end_time' => 174.75, 'target_text' => 'Appreciate those who are with you.', 'source_text' => 'Hargailah mereka yang berada di samping anda.', 'order' => 44],
            ['start_time' => 174.85, 'end_time' => 177.71, 'target_text' => 'You don\'t know how long they will be with you.', 'source_text' => 'Anda tidak tahu berapa lama lagi mereka akan bersama anda.', 'order' => 45],
            ['start_time' => 177.81, 'end_time' => 186.55, 'target_text' => 'You know, there was a time when it used to move more in a way that the older people pass on first, and the younger ones bury', 'source_text' => 'Anda tahu, suatu ketika dahulu keadaannya lazim berlaku di mana orang yang lebih berusia meninggal dunia terlebih dahulu, dan golongan muda yang mengebumikan', 'order' => 46],
            ['start_time' => 186.65, 'end_time' => 186.84, 'target_text' => 'them.', 'source_text' => 'mereka.', 'order' => 47],
