            ['start_time' => 1884.63, 'end_time' => 1886.53, 'target_text' => 'May Allah help us to help one another.', 'source_text' => 'Semoga Allah memudahkan kita untuk saling tolong-menolong antara satu sama lain.', 'order' => 561],
            ['start_time' => 1886.63, 'end_time' => 1888.21, 'target_text' => 'May we be there for one another.', 'source_text' => 'Semoga kita sentiasa ada untuk menyokong saudara-saudara kita.', 'order' => 562],
